<span class="line"><span style="--shiki-light:#998418;--shiki-dark:#B8A965;">    email</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">:</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> zhihao@example.com</span></span>
